async function next({ event, settings, acknowledge, resolution, confirmedGuests }, ctx) {
  const p = event.payload,
    s = p?.scheduled_event,
    booking = event.event === "invitee.created";
  if (!["invitee.created", "invitee.canceled"].includes(event.event) || !p?.uri || !p.email || !s)
    throw Error("Expected a Calendly invitee event");
  if (
    !settings.listId ||
    !settings.bookingTagId ||
    !settings.cancellationTagId ||
    !settings.fields ||
    Object.values(settings.fields).some((v) => typeof v !== "string" || !v || v.startsWith("YOUR_"))
  )
    throw Error("Configure KlickTipp list, tags and fields");
  const key = "calendly-klicktipp:" + event.event + ":" + p.uri;
  let state = await ctx.state.get(key);
  if (!state) {
    state = {
      phase: "invitee",
      rescheduled: !!p.rescheduled,
      guests: booking ? (s.event_guests || []).map((g) => g.email) : [],
      index: 0,
      pending: null,
    };
    await ctx.state.set(key, state);
  }
  if (state.pending) {
    if (acknowledge !== state.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending write " + state.pending);
    if (resolution === "confirmed") {
      if (state.phase === "invitee") {
        if (!booking) {
          let v;
          if (!confirmedGuests) throw Error("Enter the saved guest addresses as a JSON array");
          try {
            v = JSON.parse(confirmedGuests);
          } catch {
            throw Error("Enter the saved guest addresses as a JSON array");
          }
          if (!Array.isArray(v)) throw Error("Enter a JSON array of saved guest addresses");
          state.guests = v;
        }
        state.phase = state.guests.length ? "guest" : "done";
      } else if (state.phase === "guest") {
        state.index++;
        state.phase =
          state.index < state.guests.length
            ? "guest"
            : !booking && !p.rescheduled
              ? "clear"
              : "done";
      } else state.phase = "done";
    }
    state.pending = null;
    await ctx.state.set(key, state);
  }
  const f = settings.fields,
    tagid = booking ? settings.bookingTagId : settings.cancellationTagId,
    base = { listid: settings.listId, tagid },
    mobile = (p.text_reminder_number || "").replace("+", "00").replace(/\s+/g, ""),
    names = (p.name || "").split(" "),
    clock = (v) => {
      const parts = new Intl.DateTimeFormat("en-GB", {
          timeZone: p.timezone,
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
          hourCycle: "h23",
        }).formatToParts(new Date(v)),
        n = Object.fromEntries(parts.map((x) => [x.type, x.value]));
      return Number(n.hour) * 3600 + Number(n.minute) * 60 + Number(n.second);
    },
    fields = booking
      ? {
          fieldFirstName: p.first_name || names.slice(0, -1).join(" "),
          fieldLastName: p.last_name || names.slice(-1).join(""),
          [f.eventName]: s.name,
          [f.joinUrl]: s.location?.join_url || "",
          [f.rescheduleUrl]: p.reschedule_url || "",
          [f.cancelUrl]: p.cancel_url || "",
          [f.start]: Math.floor(Date.parse(s.start_time) / 1000),
          [f.end]: Math.floor(Date.parse(s.end_time) / 1000),
          [f.localStart]: Math.floor(
            new Date(
              new Date(s.start_time).toLocaleString("en-US", { timeZone: p.timezone }),
            ).getTime() / 1000,
          ),
          [f.localEnd]: Math.floor(
            new Date(
              new Date(s.end_time).toLocaleString("en-US", { timeZone: p.timezone }),
            ).getTime() / 1000,
          ),
          [f.startTime]: clock(s.start_time),
          [f.endTime]: clock(s.end_time),
          [f.timezone]: p.timezone,
          [f.guests]: JSON.stringify(state.guests),
        }
      : {};
  let body = {};
  if (state.phase === "invitee")
    body = {
      ...base,
      email: p.email,
      ...(mobile ? { smsnumber: mobile } : {}),
      ...(booking ? { fields } : {}),
    };
  if (state.phase === "guest")
    body = {
      ...base,
      email: state.guests[state.index],
      ...(booking
        ? {
            fields: Object.fromEntries(
              Object.entries(fields).filter(
                ([k]) => !["fieldFirstName", "fieldLastName", f.guests].includes(k),
              ),
            ),
          }
        : {}),
    };
  if (state.phase === "clear") body = { ...base, email: p.email, fields: { [f.guests]: "" } };
  if (state.phase !== "done") {
    state.pending = state.phase + ":" + state.index + ":" + key;
    await ctx.state.set(key, state);
  }
  return { key, phase: state.phase, body, booking, guestField: f.guests };
}

async function confirm({ key, phase, body, statusCode, booking, guestField }, ctx) {
  const state = await ctx.state.get(key);
  if (!state || state.phase !== phase || !state.pending)
    throw Error("Missing pending subscriber write");
  if (statusCode < 200 || statusCode >= 300 || !body || !body.id)
    throw Error("Subscriber write not confirmed");
  if (phase === "invitee") {
    if (!booking) {
      const value = body[guestField] || "";
      state.guests = value ? JSON.parse(value.replace(/&quot;/g, '"')) : [];
      if (!Array.isArray(state.guests)) throw Error("Invalid stored guest list");
    }
    state.phase = state.guests.length ? "guest" : "done";
  } else if (phase === "guest") {
    state.index++;
    state.phase =
      state.index < state.guests.length
        ? "guest"
        : !booking && !state.rescheduled
          ? "clear"
          : "done";
  } else state.phase = "done";
  state.pending = null;
  await ctx.state.set(key, state);
  return { ok: true };
}

export default async function run(
  { event, username, password, settings, acknowledge, resolution, confirmedGuests },
  ctx,
) {
  const login = await ctx.fetch("https://api.klicktipp.com/account/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password }),
  });
  if (!login.ok) throw Error("KlickTipp login failed");
  const session = await login.json();
  if (!session.session_name || !session.sessid) throw Error("KlickTipp login returned no session");
  const cookie = session.session_name + "=" + session.sessid;
  let ack = acknowledge,
    resolve = resolution,
    guests = confirmedGuests;
  for (let i = 0; i < 1000; i++) {
    const step = await next(
      { event, settings, acknowledge: ack, resolution: resolve, confirmedGuests: guests },
      ctx,
    );
    ack = "";
    resolve = "";
    guests = "";
    if (step.phase === "done") return { ok: true };
    const response = await ctx.fetch("https://api.klicktipp.com/subscriber", {
      method: "POST",
      headers: { "Content-Type": "application/json", Cookie: cookie },
      body: JSON.stringify(step.body),
    });
    const body = await response.json();
    await confirm(
      {
        key: step.key,
        phase: step.phase,
        body,
        statusCode: response.status,
        booking: step.booking,
        guestField: step.guestField,
      },
      ctx,
    );
  }
  throw Error("Too many subscribers in this event");
}
